    gradientHero:  'radial-gradient(ellipse 60% 60% at 50% 60%, rgba(58,125,0,0.06) 0%, transparent 70%)',
  },
};

const ThemeContext = createContext({ mode: 'dark', theme: themes.dark, toggle: () => {} });

export const ThemeProvider = ({ children }) => {
  const [mode, setMode] = useState(() => localStorage.getItem('portfolio-theme') || 'dark');

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', mode);
    localStorage.setItem('portfolio-theme', mode);
  }, [mode]);

  const toggle = () => setMode(m => (m === 'dark' ? 'light' : 'dark'));
  const theme = themes[mode];

  return (
    <ThemeContext.Provider value={{ mode, theme, toggle }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => useContext(ThemeContext);

import { useRef } from 'react';
import { motion, useInView } from 'framer-motion';
import { useTheme } from '../context/ThemeContext';

const stats = [
  { value: '3+', label: 'Years Experience' },
  { value: '20+', label: 'Projects Built' },
  { value: '10+', label: 'Tech Stacks' },
  { value: '∞', label: 'Cups of Coffee' },
];

const About = () => {
  const ref = useRef(null);
  const inView = useInView(ref, { once: true, margin: '-100px' });
  const { theme } = useTheme();

  const stagger = {
    hidden: {},
    visible: { transition: { staggerChildren: 0.12 } },
  };

  const item = {
    hidden: { opacity: 0, y: 40 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.8, ease: [0.16, 1, 0.3, 1] } },
  };

  return (
    <section
      id="about"
      ref={ref}
      style={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        padding: '8rem 3rem',
        maxWidth: '1200px',
        margin: '0 auto',
      }}
    >
      <div style={{ width: '100%' }}>
        {/* Section header */}
        <motion.div
          initial={{ opacity: 0, x: -30 }}
          animate={inView ? { opacity: 1, x: 0 } : {}}
          transition={{ duration: 0.6 }}
          style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '4rem' }}
        >
          <span className="section-num" style={{ color: theme.muted }}>01</span>
          <span style={{ width: '3rem', height: '1px', background: theme.borderHover }} />
          <span style={{ color: theme.muted, fontFamily: "'Space Mono', monospace", fontSize: '0.75rem', letterSpacing: '0.15em' }}>ABOUT</span>
        </motion.div>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '6rem', alignItems: 'start' }}>
          {/* Left: text */}
          <motion.div
            variants={stagger}
            initial="hidden"
            animate={inView ? 'visible' : 'hidden'}
          >
            <motion.h2
              variants={item}
              data-text="Hello, I'm Ayush"
              className="glitch"
              style={{
                fontSize: 'clamp(2rem, 5vw, 3.5rem)',
                fontWeight: 700,
                letterSpacing: '-0.03em',
                marginBottom: '1.5rem',
                color: theme.text,
              }}
            >
              Hello, I'm Ayush
            </motion.h2>

            <motion.p variants={item} style={{ color: theme.textSub, lineHeight: 1.9, marginBottom: '1.2rem', fontSize: '1.05rem' }}>
              I'm a full-stack developer and creative coder passionate about building
              things that live on the internet. I specialize in crafting immersive
              web experiences that blend aesthetic finesse with technical precision.
            </motion.p>

            <motion.p variants={item} style={{ color: theme.muted, lineHeight: 1.9, marginBottom: '1.2rem', fontSize: '1.05rem' }}>
              Currently pursuing my degree while simultaneously building production-grade
              applications. I believe the best software is both functional <em>and</em> beautiful —
