import { useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import * as THREE from 'three';
import { useTheme } from '../context/ThemeContext';

const Hero = () => {
  const canvasRef = useRef(null);
  const { theme } = useTheme();

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: false });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(canvas.clientWidth, canvas.clientHeight);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(60, canvas.clientWidth / canvas.clientHeight, 0.1, 1000);
    camera.position.z = 5;

    const count = 4000;
    const positions = new Float32Array(count * 3);
    const speeds = new Float32Array(count);

    for (let i = 0; i < count; i++) {
      positions[i * 3]     = (Math.random() - 0.5) * 18;
      positions[i * 3 + 1] = (Math.random() - 0.5) * 18;
      positions[i * 3 + 2] = (Math.random() - 0.5) * 18;
      speeds[i] = 0.0002 + Math.random() * 0.0006;
    }

    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

    const hex = theme.particleColor.replace('#', '');
    const particleColor = parseInt(hex, 16);

    const material = new THREE.PointsMaterial({
      color: particleColor,
      size: 0.015,
      transparent: true,
      opacity: 0.7,
      sizeAttenuation: true,
    });

    const particles = new THREE.Points(geometry, material);
    scene.add(particles);

    let mouseX = 0, mouseY = 0;
    const onMouseMove = (e) => {
      mouseX = (e.clientX / window.innerWidth - 0.5) * 2;
      mouseY = -(e.clientY / window.innerHeight - 0.5) * 2;
    };
    window.addEventListener('mousemove', onMouseMove);

    const resize = () => {
      const w = canvas.clientWidth;
      const h = canvas.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };
    window.addEventListener('resize', resize);

    let animId;
    const animate = () => {
      const pos = geometry.attributes.position.array;
      for (let i = 0; i < count; i++) {
        pos[i * 3 + 1] -= speeds[i];
        if (pos[i * 3 + 1] < -9) pos[i * 3 + 1] = 9;
      }
      geometry.attributes.position.needsUpdate = true;
      particles.rotation.y += 0.0003;
      particles.rotation.x += 0.0001;
      camera.position.x += (mouseX * 0.5 - camera.position.x) * 0.02;
      camera.position.y += (mouseY * 0.5 - camera.position.y) * 0.02;
      camera.lookAt(scene.position);
      renderer.render(scene, camera);
      animId = requestAnimationFrame(animate);
    };
    animate();

    return () => {
      cancelAnimationFrame(animId);
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('resize', resize);
      renderer.dispose();
      geometry.dispose();
      material.dispose();
    };
  }, [theme.particleColor]);

  const letterVariants = {
    hidden: { y: '110%' },
    visible: (i) => ({
      y: 0,
      transition: { duration: 0.8, delay: i * 0.04, ease: [0.16, 1, 0.3, 1] },
    }),
  };

  const splitText = (text) =>
    text.split('').map((char, i) => (
      <motion.span key={i} custom={i} variants={letterVariants}
        style={{ display: 'inline-block', whiteSpace: char === ' ' ? 'pre' : 'normal' }}>
        {char}
      </motion.span>
    ));

  return (
    <section id="hero" style={{
      position: 'relative', height: '100vh',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      overflow: 'hidden', transition: 'background 0.5s ease',
    }}>
      <canvas ref={canvasRef} style={{
        position: 'absolute', inset: 0, width: '100%', height: '100%', pointerEvents: 'none',
      }} />

      <div style={{
        position: 'absolute', inset: 0,
        background: theme.gradientHero,
        pointerEvents: 'none',
      }} />

      <div style={{ position: 'relative', zIndex: 10, textAlign: 'center', padding: '0 2rem' }}>
        {/* Tag line */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.3 }}
          style={{
            fontFamily: "'Space Mono', monospace", fontSize: '0.75rem',
            color: theme.accent, letterSpacing: '0.25em', textTransform: 'uppercase',
            marginBottom: '1.5rem', display: 'flex', alignItems: 'center',
            justifyContent: 'center', gap: '1rem',
          }}
        >
          <span style={{ width: '2rem', height: '1px', background: theme.accent }} />
          Full Stack Developer & Designer
          <span style={{ width: '2rem', height: '1px', background: theme.accent }} />
        </motion.div>

        {/* First name */}
        <motion.h1
          initial="hidden" animate="visible" transition={{ delayChildren: 0.4 }}
          style={{
            fontSize: 'clamp(3.5rem, 10vw, 9rem)', fontWeight: 700,
            lineHeight: 0.9, letterSpacing: '-0.04em',
            color: theme.text, overflow: 'hidden', marginBottom: '0.25rem',
          }}
        >
          {splitText('AYUSH')}
        </motion.h1>

        {/* Last name */}
        <motion.h1
          initial="hidden" animate="visible" transition={{ delayChildren: 0.6 }}
          style={{
            fontSize: 'clamp(3.5rem, 10vw, 9rem)', fontWeight: 700,
